    {
      "id": "lowest-price",
      "label": "Lowest Price",
      "value": "$0.30",
      "unit": "per 1M tokens",
      "context": "gpt-oss-120B (high) and DeepSeek V3.2 tied as cheapest"
    },
    {
      "id": "highest-price",
      "label": "Highest Price",
      "value": "$10.00",
      "unit": "per 1M tokens",
