cat << 'LATEX_EOF' > /app/poster/main.tex
\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ══ Dark-mode Dashboard Color Theme ══
\definecolor{pagebg}{HTML}{0D1117}
\definecolor{cardbg}{HTML}{161B22}
\definecolor{cardborder}{HTML}{30363D}
\definecolor{textprimary}{HTML}{E6EDF3}
\definecolor{textsecondary}{HTML}{8B949E}
\definecolor{electricblue}{HTML}{58A6FF}
\definecolor{tealgreen}{HTML}{2DD4BF}
\definecolor{warmamber}{HTML}{F0883E}
\definecolor{coral}{HTML}{FF7B72}
\definecolor{deepblue}{HTML}{1F6FEB}
\definecolor{statbg}{HTML}{1A2332}
\definecolor{titlebg}{HTML}{0D1117}
\definecolor{methodbg}{HTML}{1C2333}
\definecolor{footerbg}{HTML}{0D1117}

\pagecolor{pagebg}
\color{textprimary}

% ══ Card Styles ══
\tcbset{
  bluecard/.style={
    enhanced, arc=4pt, boxrule=0.5pt,
    colback=cardbg, colframe=cardborder,
    borderline north={3pt}{0pt}{electricblue},
    left=10pt, right=10pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{electricblue},
    coltitle=electricblue, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  tealcard/.style={
    enhanced, arc=4pt, boxrule=0.5pt,
    colback=cardbg, colframe=cardborder,
    borderline north={3pt}{0pt}{tealgreen},
    left=10pt, right=10pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{tealgreen},
    coltitle=tealgreen, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  ambercard/.style={
    enhanced, arc=4pt, boxrule=0.5pt,
    colback=cardbg, colframe=cardborder,
    borderline north={3pt}{0pt}{warmamber},
    left=10pt, right=10pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{warmamber},
    coltitle=warmamber, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  herocard/.style={
    enhanced, arc=4pt, boxrule=0.5pt,
    colback=cardbg, colframe=cardborder,
    borderline north={4pt}{0pt}{coral},
    left=10pt, right=10pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{30}{36}\selectfont\bfseries\color{coral},
    coltitle=coral, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  statbox/.style={
    enhanced, arc=6pt, boxrule=0.5pt,
    colback=statbg, colframe=cardborder,
    left=8pt, right=8pt, top=6pt, bottom=6pt,
    valign=center, halign=center,
  },
  methodcard/.style={
    enhanced, arc=4pt, boxrule=0.5pt,
    colback=cardbg, colframe=cardborder,
    borderline north={3pt}{0pt}{textsecondary},
    left=10pt, right=10pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{22}{28}\selectfont\bfseries\color{textsecondary},
    coltitle=textsecondary, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=4pt,
    titlerule=0pt,
    valign=top,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=4mm},
]

% ══════════════════════════════════════════════
% TITLE BAR
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=pagebg, colframe=pagebg, colupper=textprimary,
  arc=0pt, boxrule=0pt,
  left=28pt, right=28pt, top=14pt, bottom=4pt,
  halign=center, valign=center,
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{52}{62}\selectfont\bfseries\color{textprimary}Frontier AI Models Compared}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{electricblue}Intelligence\color{textsecondary}\enspace\textbullet\enspace\color{tealgreen}Speed\color{textsecondary}\enspace\textbullet\enspace\color{warmamber}Cost}\\[10pt]
  {\fontsize{18}{24}\selectfont\color{textsecondary}Based on the Artificial Analysis Intelligence Index v4.0\enspace|\enspace artificialanalysis.ai\enspace|\enspace April 2026}
}

% ══════════════════════════════════════════════
% STAT BANNER — 3 headline callouts
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=pagebg, colframe=pagebg,
  arc=0pt, boxrule=0pt,
  left=12pt, right=12pt, top=2pt, bottom=2pt,
  valign=center,
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \begin{tcolorbox}[statbox]
      {\fontsize{54}{64}\selectfont\bfseries\color{electricblue}57}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textsecondary}Top Intelligence Score}\\[2pt]
      {\fontsize{14}{18}\selectfont\color{textsecondary}Gemini 3.1 Pro \& GPT-5.4 tied}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \begin{tcolorbox}[statbox]
      {\fontsize{54}{64}\selectfont\bfseries\color{tealgreen}206}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textsecondary}Tokens/sec Speed Leader}\\[2pt]
      {\fontsize{14}{18}\selectfont\color{textsecondary}gpt-oss-120B (high)}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \begin{tcolorbox}[statbox]
      {\fontsize{54}{64}\selectfont\bfseries\color{warmamber}33\texttimes}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textsecondary}Price Range Factor}\\[2pt]
      {\fontsize{14}{18}\selectfont\color{textsecondary}\$0.30 to \$10.00 per 1M tokens}
    \end{tcolorbox}
  \end{minipage}
}

% ══════════════════════════════════════════════
% INTELLIGENCE RANKINGS (left column)
% ══════════════════════════════════════════════
\posterbox[bluecard, title={\raisebox{0pt}{\color{electricblue}\rule[-2pt]{3pt}{18pt}}\enspace Intelligence Rankings}
]{name=intel, column=1, between=row5 and row11}{
  \centering
  \includegraphics[width=0.98\linewidth]{figures/intelligence.png}\\[4pt]
  {\fontsize{15}{20}\selectfont\color{textsecondary}%
  Gemini 3.1 Pro Preview \& GPT-5.4 share the lead at \textbf{\color{electricblue}57}. A 24-point gap separates leaders from the budget tier.}
}

% ══════════════════════════════════════════════
% SPEED COMPARISON (right column)
% ══════════════════════════════════════════════
\posterbox[tealcard, title={\raisebox{0pt}{\color{tealgreen}\rule[-2pt]{3pt}{18pt}}\enspace Output Speed Comparison}
]{name=speed, column=2, between=row5 and row11}{
  \centering
  \includegraphics[width=0.98\linewidth]{figures/speed.png}\\[4pt]
  {\fontsize{15}{20}\selectfont\color{textsecondary}%
  The fastest model (gpt-oss-120B at \textbf{\color{tealgreen}206 tok/s}) ranks \textbf{last} in intelligence. Speed $\neq$ smarts.}
}

% ══════════════════════════════════════════════
% PRICING LANDSCAPE (full width)
% ══════════════════════════════════════════════
\posterbox[ambercard, title={\raisebox{0pt}{\color{warmamber}\rule[-2pt]{3pt}{18pt}}\enspace Pricing Landscape}
]{name=pricing, column=1, span=2, between=row11 and row15}{
  \centering
  \includegraphics[width=0.98\linewidth]{figures/pricing.png}\\[4pt]
  {\fontsize{15}{20}\selectfont\color{textsecondary}%
  The cheapest options (gpt-oss-120B \& DeepSeek V3.2 at \textbf{\color{warmamber}\$0.30}) cost \textbf{\color{warmamber}33\texttimes{}} less than Claude Opus 4.6 at \$10.00. Premium intelligence demands a steep price premium.}
}

% ══════════════════════════════════════════════
% TRADE-OFF ANALYSIS — HERO SECTION (full width)
% ══════════════════════════════════════════════
\posterbox[herocard, title={\raisebox{0pt}{\color{coral}\rule[-2pt]{3pt}{20pt}}\enspace The Intelligence--Speed--Cost Trade-Off}
]{name=tradeoff, column=1, span=2, between=row15 and row19}{
  \begin{minipage}[t]{0.65\linewidth}
    \centering
    \includegraphics[width=\linewidth]{figures/tradeoff.png}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.33\linewidth}
    \vspace{4pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{coral}Key Insights}\\[10pt]
    {\fontsize{15}{22}\selectfont\color{textprimary}%
    \textbf{\color{electricblue}Best Intelligence}\\
    Gemini 3.1 Pro \& GPT-5.4 (57) --- mid-to-high cost (\$4.50--\$5.60)\\[8pt]
    \textbf{\color{tealgreen}Best Value}\\
    gpt-oss-120B: fastest (206 tok/s), cheapest (\$0.30), but lowest IQ (33)\\[8pt]
    \textbf{\color{warmamber}Balanced Pick}\\
    Gemini 3 Flash: 46 IQ, 149 tok/s, just \$1.10 --- strong middle ground\\[8pt]
    \textbf{\color{coral}Premium Tier}\\
    Claude Opus 4.6: 53 IQ but slowest (40 tok/s) and most expensive (\$10.00)\\[10pt]
    }
    {\fontsize{15}{20}\selectfont\color{textsecondary}\textit{There is no single ``best'' model --- the right choice depends on which dimension matters most.}}
  \end{minipage}
}

% ══════════════════════════════════════════════
% METHODOLOGY FOOTER
% ══════════════════════════════════════════════
\posterbox[methodcard, title={\raisebox{0pt}{\color{textsecondary}\rule[-2pt]{3pt}{16pt}}\enspace About the Index}
]{name=method, column=1, span=2, between=row19 and bottom}{
  {\fontsize{14}{20}\selectfont\color{textsecondary}%
  The Artificial Analysis Intelligence Index v4.0 aggregates 10 independent evaluations: GDPval-AA, $\tau^2$-Bench Telecom, Terminal-Bench Hard, SciCode, AA-LCR, AA-Omniscience, IFBench, Humanity's Last Exam, GPQA Diamond, and CritPt. Scores span coding, agentic tasks, scientific reasoning, knowledge accuracy, hallucination resistance, and instruction following. All measurements conducted independently under standardized conditions.\hfill\textbf{\color{electricblue}artificialanalysis.ai}}
}

\end{tcbposter}
\end{document}
LATEX_EOF
echo "LaTeX file written."

